-- =============================================================================
-- 443 — LE CAHIER D'EXERCICES DE TLE (partie 8)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 443 --niveau Tle --matieres hlp,musique --suffixe 8 > supabase/contenu/443_exercices_tle_8.sql
--
-- 99 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   hlp.k161                33 exercices · 11 chapitres
--   hlp.k162                30 exercices · 10 chapitres
--   musique.k178            36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('cee613e0-8d08-598a-86a2-22bdefbc269d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce qui ne dépend de personne","competence":"analyser-texte","situation":"Pour ton oral, tu relis un passage adapté de Lévi-Strauss sur le partage entre nature et culture. Repère le critère, range des exemples, puis remets le raisonnement dans l’ordre.","documents":[{"id":"ls","type":"texte","genre":"source","titre":"Un critère de partage","blocs":["Tout ce qui est universel chez l’homme relève de la nature, car cela ne dépend d’aucune société. Tout ce qui est soumis à une règle propre à chaque groupe relève de la culture, car cela varie d’une société à l’autre. Or la prohibition de l’inceste se retrouve partout, et pourtant chaque société la règle à sa façon : elle brouille la frontière."],"source":"D’après Lévi-Strauss, *Les Structures élémentaires de la parenté* (1949) — texte adapté"}],"questions":[{"enonce":"Touche le mot qui donne le critère de ce qui est naturel.","aide":"Le naturel, c’est ce qui se retrouve chez tous les humains.","type":"zone","document":"ls","multiple":false},{"enonce":"Range chaque exemple du côté de la nature ou de la culture.","aide":"Cherche ce qui est identique partout, et ce qui change d’une société à l’autre.","type":"categories","categories":[{"id":"c0","texte":"Nature"},{"id":"c1","texte":"Culture"}],"items":[{"id":"i0","texte":"Les règles de parenté"},{"id":"i1","texte":"Le vêtement"},{"id":"i2","texte":"La table"},{"id":"i3","texte":"Dormir"},{"id":"i4","texte":"Marcher"}]},{"enonce":"Remets dans l’ordre le raisonnement du texte.","aide":"Le texte pose le critère, observe un cas, puis conclut.","type":"ordre","items":[{"id":"a","texte":"On constate que chaque société la règle pourtant à sa façon"},{"id":"b","texte":"On pose un critère : l’universel est naturel, la règle qui varie est culturelle"},{"id":"c","texte":"On en conclut que l’inceste brouille la frontière entre nature et culture"},{"id":"d","texte":"On observe que la prohibition de l’inceste est présente partout"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"Le mot est **universel** : ce qui se retrouve partout relève de la nature."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"**Dormir** et **marcher** se retrouvent partout (nature) ; **la table, le vêtement et les règles de parenté** varient selon les sociétés (culture)."},{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"Le texte **pose le critère, observe le cas de l’inceste, relève sa double nature, puis conclut** que la frontière est brouillée."}]$ex$::jsonb),
  ('cee613e0-8d08-598a-86a2-22bdefbc269d'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un fonctionnaire comme les autres","competence":"analyser-document","situation":"Un journaliste imaginaire assiste à un procès et note ce qu’il voit. Relie-le à ce que Hannah Arendt a appelé la banalité du mal, puis retrouve les trois auteurs du chapitre.","documents":[{"id":"jrn","type":"texte","genre":"article","titre":"Carnet d’audience","blocs":["Quand l’accusé prend la parole, la salle s’attend à un monstre. Elle entend un employé soigneux. Il répète des formules toutes faites, dit avoir obéi aux ordres et suivi la procédure, sans jamais paraître haïr personne.","Ce qui glace, ce n’est pas sa cruauté : c’est qu’il n’y en a pas, et que des milliers d’hommes pareils à lui ont rendu le crime possible."],"source":"Carnet imaginaire, écrit pour l’exercice, dans l’esprit d’Arendt"}],"questions":[{"enonce":"Touche le mot qui montre que l’accusé se décharge sur un système.","aide":"Quelle action dit qu’il a suivi des ordres venus d’ailleurs ?","type":"zone","document":"jrn","multiple":false},{"enonce":"Quelle lecture du texte est celle de la « banalité du mal » ?","aide":"Relis la deuxième phrase du carnet : il n’y a pas de cruauté visible.","type":"choix","options":[{"id":"a","texte":"Le crime est ici le fait d’un homme ordinaire, dans un système qui obéit"},{"id":"b","texte":"Le crime est ici un accident que personne n’aurait pu prévoir ni empêcher"},{"id":"c","texte":"Le crime est ici une erreur de procédure qui ne met personne en cause"},{"id":"d","texte":"Le crime est ici le fait d’un sadique isolé, que rien ne rattache à son temps"}],"multiple":false},{"enonce":"Associe chaque auteur à l’œuvre ou à l’idée qui lui correspond.","aide":"Un témoin, une analyste du procès, un penseur de la technique.","type":"association","gauche":[{"id":"g0","texte":"Primo Levi"},{"id":"g1","texte":"Hannah Arendt"},{"id":"g2","texte":"Hans Jonas"}],"droite":[{"id":"d0","texte":"Eichmann à Jérusalem, la banalité du mal"},{"id":"d1","texte":"Si c’est un homme, témoignage du camp"},{"id":"d2","texte":"Le Principe responsabilité, face à la technique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"Le mot est **obéi** : il se présente comme un rouage qui a exécuté les ordres."},{"cle":{"type":"choix","ids":["a"]},"explication":"La **banalité du mal** désigne le crime commis par des hommes ordinaires, dans un système obéissant."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Levi** témoigne du camp, **Arendt** analyse le procès d’Eichmann (1963), **Jonas** pense la responsabilité face à la technique (1979)."}]$ex$::jsonb),
  ('cee613e0-8d08-598a-86a2-22bdefbc269d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Augmenter l’humain : accomplir ou supprimer ?","competence":"argumenter","situation":"Une entreprise imaginaire vante l’augmentation de l’humain. Confronte sa publicité aux deux définitions de l’humain, trie les arguments, puis complète la problématique d’un essai.","documents":[{"id":"pub","type":"texte","genre":"article","titre":"Publicité d’une entreprise fictive","blocs":["**Dépasse tes limites.** Mémoire doublée, vieillissement ralenti : avec notre programme, l’humain n’a plus de frontière. Un être qui se transforme sans cesse, voilà ce que nous sommes. Refuser l’augmentation, c’est refuser de devenir soi."],"source":"Texte publicitaire imaginaire, écrit pour l’exercice"},{"id":"def","type":"tableau","titre":"Deux définitions de l’humain","colonnes":["","Première réponse","Seconde réponse"],"lignes":[["Ce qui définit l’humain","Sa perfectibilité","Sa finitude"],["L’humain est…","l’être qui se transforme","l’être qui sait qu’il meurt"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot de la publicité qui renvoie à la perfectibilité.","aide":"Cherche le verbe qui dit que l’humain se change lui-même.","type":"zone","document":"pub","multiple":false},{"enonce":"Range chaque argument du côté de la perfectibilité ou de la finitude.","aide":"Un camp valorise le changement, l’autre la limite.","type":"categories","categories":[{"id":"c0","texte":"Perfectibilité"},{"id":"c1","texte":"Finitude"}],"items":[{"id":"i0","texte":"L’humain est l’être qui se change lui-même"},{"id":"i1","texte":"Supprimer toute limite ferait disparaître ce qui nous définit"},{"id":"i2","texte":"Améliorer le corps prolonge ce que l’humain a toujours fait"},{"id":"i3","texte":"Savoir qu’on meurt donne son prix au temps"}]},{"enonce":"Quel argument de Hans Jonas pourrait-on opposer à la publicité ?","aide":"Pense au principe responsabilité : on regarde les effets de l’action.","type":"choix","options":[{"id":"a","texte":"Il faut mesurer si les effets de l’action restent compatibles avec une vie humaine"},{"id":"b","texte":"Il faut laisser chacun agir selon son intérêt immédiat, sans considérer les suites"},{"id":"c","texte":"Il faut accélérer toute nouvelle technique pour ne pas retarder le progrès"},{"id":"d","texte":"Il faut interdire d’avance toute technique qui touche au corps humain"}],"multiple":false},{"enonce":"Complète la problématique d’un essai.","aide":"C’est la tension finale du chapitre.","type":"trous","segments":["Augmenter l’humain, est-ce l’",0," ou le ",1," ?"],"banque":["accomplir","punir","supprimer","nourrir"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Le mot est **transforme** : la publicité défend la première définition, la perfectibilité."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Les deux premiers arguments défendent la **perfectibilité**, les deux autres la **finitude**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **principe responsabilité** demande que les effets de l’action restent compatibles avec la permanence d’une vie humaine authentique."},{"cle":{"type":"trous","trous":[["accomplir"],["supprimer"]]},"affichage":"accomplir · supprimer","explication":"Le chapitre se clôt sur cette tension : augmenter l’humain, est-ce l’**accomplir** ou le **supprimer** ?"}]$ex$::jsonb),
  ('245d7288-4db0-5e78-847e-1826becffcfe'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’horoscope qui ne se trompe jamais","competence":"analyser-document","situation":"Léa et Malik discutent d’une prévision astrologique. Trouve ce qui cloche, retrouve la notion de Popper et associe les trois penseurs du chapitre à leur idée.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Un échange entre amis","participants":[{"nom":"Malik","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Malik","texte":"Mon horoscope ne se trompe jamais : s’il fait beau, c’était écrit ; s’il pleut, c’était écrit aussi."},{"qui":"Léa","texte":"Alors il n’annonce rien : aucun fait ne pourrait le démentir."}]}],"questions":[{"enonce":"Touche le mot de Léa qui dit ce qui manque à l’horoscope.","aide":"Que ne peut-on jamais faire avec une prévision qui a toujours raison ?","type":"zone","document":"sms","multiple":false},{"enonce":"Selon Popper, que manque-t-il à l’horoscope de Malik pour être scientifique ?","aide":"Popper ne demande ni l’accord ni les succès passés.","type":"choix","options":[{"id":"a","texte":"Une prévision qu’un fait pourrait réfuter"},{"id":"b","texte":"Une prévision acceptée par la majorité"},{"id":"c","texte":"Une prévision qui s’est toujours vérifiée"},{"id":"d","texte":"Une prévision qu’un astronome aurait signée"}],"multiple":false},{"enonce":"Associe chaque penseur à son idée.","aide":"Réfutable, paradigme, construit.","type":"association","gauche":[{"id":"g0","texte":"Popper"},{"id":"g1","texte":"Kuhn"},{"id":"g2","texte":"Bachelard"}],"droite":[{"id":"d0","texte":"La science ordinaire travaille dans un paradigme"},{"id":"d1","texte":"Le fait scientifique est construit"},{"id":"d2","texte":"La théorie scientifique est réfutable"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m30"]},"explication":"Le mot est **démentir** : une théorie scientifique doit pouvoir être contredite par un fait."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une théorie est scientifique si elle est **réfutable** : un fait doit pouvoir la contredire."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Popper** : réfutabilité ; **Kuhn** : paradigme ; **Bachelard** : le fait est construit contre l’expérience première."}]$ex$::jsonb),
  ('245d7288-4db0-5e78-847e-1826becffcfe'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Quand le paradigme bascule","competence":"raisonner","situation":"Des astronomes d’une cité imaginaire calculent avec un vieux modèle qui accumule les écarts. Suis le cycle décrit par Kuhn, puis démasque trois confusions classiques de dissertation.","documents":[{"id":"cyc","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"La science ordinaire travaille dans un paradigme"},{"id":"z2","texte":"Les anomalies s’accumulent"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Un nouveau cadre s’impose"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche l’étape qui correspond aux écarts que le modèle n’explique plus.","aide":"Cherche le mot qui désigne ce qui résiste au modèle.","type":"zone","document":"cyc","multiple":false},{"enonce":"Quelle étape remplace le « ? » dans le cycle de Kuhn ?","aide":"Après l’accumulation des anomalies, quelque chose cède.","type":"choix","options":[{"id":"a","texte":"Le paradigme est enfin prouvé"},{"id":"b","texte":"La science cesse toute recherche"},{"id":"c","texte":"Les savants ignorent les écarts"},{"id":"d","texte":"Le paradigme finit par basculer"}],"multiple":false},{"enonce":"Trie les phrases : confusion à éviter ou idée exacte ?","aide":"Trois phrases déforment un mot, trois le définissent.","type":"categories","categories":[{"id":"c0","texte":"Confusion à éviter"},{"id":"c1","texte":"Idée exacte"}],"items":[{"id":"i0","texte":"Paradigme veut dire cadre partagé de problèmes et de méthodes"},{"id":"i1","texte":"Réfutable veut dire faux"},{"id":"i2","texte":"Réfutable veut dire qu’un fait pourrait la démentir"},{"id":"i3","texte":"Paradigme veut dire simple opinion"},{"id":"i4","texte":"Construit veut dire bâti contre l’expérience première"},{"id":"i5","texte":"Construit veut dire arbitraire"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est l’étape des **anomalies** : les observations que le paradigme n’explique pas."},{"cle":{"type":"choix","ids":["d"]},"explication":"Quand les anomalies s’accumulent, **le paradigme finit par basculer** : c’est la rupture décrite par Kuhn."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Les trois premières **confondent** les notions ; les trois autres les définissent correctement."}]$ex$::jsonb),
  ('245d7288-4db0-5e78-847e-1826becffcfe'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les faits disent-ils ce qu’il faut faire ?","competence":"argumenter","situation":"Un communiqué imaginaire passe des données à une décision. Repère le saut, trie faits et devoirs, puis complète le principe de Weber.","documents":[{"id":"com","type":"texte","genre":"article","titre":"Communiqué d’une association fictive","blocs":["Le lac de Valmont a perdu la moitié de son eau en dix ans. Les données sont claires : nous devons donc interdire toute baignade dès cet été."],"source":"Communiqué imaginaire, écrit pour l’exercice"},{"id":"ce","type":"tableau","titre":"Ce que la science établit, ou non","colonnes":["","Elle établit","Elle n’établit pas"],"lignes":[["Nature de l’énoncé","Ce qui est","Ce qui doit être"],["Exemple","Une donnée mesurée","La politique à mener"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot où le communiqué passe d’un fait à un devoir.","aide":"Cherche le petit mot qui tire une conséquence.","type":"zone","document":"com","multiple":false},{"enonce":"Range chaque énoncé : fait ou devoir ?","aide":"Un fait se constate ; un devoir se décide.","type":"categories","categories":[{"id":"c0","texte":"Fait"},{"id":"c1","texte":"Devoir"}],"items":[{"id":"i0","texte":"Il faut limiter l’usage de l’eau"},{"id":"i1","texte":"On a le droit d’employer cette technique partout"},{"id":"i2","texte":"Ce lac a perdu la moitié de son eau en dix ans"},{"id":"i3","texte":"Cette technique permet de dessaler l’eau de mer"}]},{"enonce":"Quelle critique Hume et Weber adresseraient-ils au communiqué ?","aide":"On ne déduit pas un devoir d’un fait.","type":"choix","options":[{"id":"a","texte":"Une donnée mesurée n’est jamais une information fiable"},{"id":"b","texte":"Une décision doit toujours rester secrète jusqu’à la fin"},{"id":"c","texte":"Une association ne devrait pas s’appuyer sur des chiffres"},{"id":"d","texte":"Une donnée seule ne dit pas la décision à prendre"}],"multiple":false},{"enonce":"Complète le principe de Weber.","aide":"Le cours parle de la chaire et de la tribune.","type":"trous","segments":["Le savant respecte la ",0," axiologique : il ne confond pas sa ",1," et sa ",2,"."],"banque":["neutralité","tribune","autorité","chaire"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"Le mot est **donc** : on passe d’un constat à une obligation, ce que la donnée seule ne permet pas."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Les deux premiers énoncés **constatent** ; les deux derniers **prescrivent**."},{"cle":{"type":"choix","ids":["d"]},"explication":"On ne déduit pas un **devoir** d’un **fait** : la décision suppose des valeurs que la donnée n’énonce pas."},{"cle":{"type":"trous","trous":[["neutralite"],["chaire"],["tribune"]]},"affichage":"neutralité · chaire · tribune","explication":"Weber demande la **neutralité** axiologique : ne pas confondre sa **chaire** et sa **tribune**."}]$ex$::jsonb),
