  ('1b407335-9135-5de3-9afd-9e5cd66da90d'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"L’aura perdue","competence":"analyser-texte","situation":"Un passage adapté de Walter Benjamin parle de ce que la reproduction fait à l’œuvre. Relève la notion clé, choisis l’interprétation juste, puis oppose Benjamin et Adorno.","documents":[{"id":"wb","type":"texte","genre":"source","titre":"Ici et maintenant","blocs":["L’œuvre unique existe en un lieu et à un moment précis : c’est son aura. La reproduction l’arrache à ce lieu et la met à la portée de tous. L’aura se perd, mais l’œuvre sort du culte pour entrer dans l’usage : c’est une chance politique."],"source":"D’après Walter Benjamin, *L’Œuvre d’art à l’époque de sa reproductibilité technique* — texte adapté"}],"questions":[{"enonce":"Touche le mot qui désigne l’unicité de l’œuvre liée à un lieu et à un moment.","aide":"Le mot est un nom rare, défini juste après les deux points.","type":"zone","document":"wb","multiple":false},{"enonce":"Pourquoi Benjamin parle-t-il d’une chance politique ?","aide":"Reproduire, c’est diffuser.","type":"choix","options":[{"id":"a","texte":"L’œuvre quitte le culte et devient accessible à un large public"},{"id":"b","texte":"L’œuvre devient moins chère et donc moins discutable"},{"id":"c","texte":"L’œuvre devient plus rare et donc réservée à une élite"},{"id":"d","texte":"L’œuvre devient plus sacrée et donc mieux protégée"}],"multiple":false},{"enonce":"Range chaque idée du côté de Benjamin ou d’Adorno.","aide":"L’un voit une chance, l’autre une menace de standardisation.","type":"categories","categories":[{"id":"c0","texte":"Benjamin"},{"id":"c1","texte":"Adorno"}],"items":[{"id":"i0","texte":"L’art résiste en n’étant pas immédiatement consommable"},{"id":"i1","texte":"La culture de masse standardise"},{"id":"i2","texte":"L’art sort du culte pour entrer dans l’usage"},{"id":"i3","texte":"La reproduction fait perdre l’aura"}]}]}$ex$::jsonb,
