  ('1b407335-9135-5de3-9afd-9e5cd66da90d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La caisse sous vitrine","competence":"argumenter","situation":"Dans un musée imaginaire, deux caisses identiques se font face. Applique les réponses de Danto et de Dickie, puis remets dans l’ordre le plan d’une dissertation.","documents":[{"id":"mus","type":"texte","genre":"article","titre":"Scène imaginaire","blocs":["Dans les réserves d’un supermarché, une caisse de lessive attend d’être vendue. Dans une salle du musée, une caisse parfaitement semblable est posée sous une vitrine, avec un cartel, un nom d’artiste et un éclairage. À l’œil nu, rien ne les distingue."],"source":"Scène imaginaire, écrite pour l’exercice, inspirée des *Boîtes Brillo* de Warhol"},{"id":"th","type":"tableau","titre":"Deux réponses à la question « qu’est-ce que l’art ? »","colonnes":["","Danto","Dickie"],"lignes":[["Ce qui fait la différence","Une différence théorique, invisible à l’œil","L’institution : un monde de l’art traite l’objet comme art"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne ce que le musée ajoute autour de la caisse.","aide":"Cherche l’objet qui protège et met en scène la caisse exposée.","type":"zone","document":"mus","multiple":false},{"enonce":"Que conclurait Danto devant les deux caisses ?","aide":"Rien de visible ne distingue les deux caisses.","type":"choix","options":[{"id":"a","texte":"La différence ne se voit pas, elle tient à une théorie"},{"id":"b","texte":"La différence tient au prix d’achat de chacune des caisses"},{"id":"c","texte":"La différence n’existe pas, donc rien n’est jamais de l’art"},{"id":"d","texte":"La différence se voit à la qualité du travail de l’artiste"}],"multiple":false},{"enonce":"Que répondrait Dickie à la question « qu’est-ce qui en fait une œuvre ? »","aide":"Pense à la définition institutionnelle.","type":"choix","options":[{"id":"a","texte":"Un monde de l’art la traite comme telle"},{"id":"b","texte":"Un siècle d’histoire la rend vénérable"},{"id":"c","texte":"Un consensus du public la trouve belle"},{"id":"d","texte":"Un savoir-faire rare la rend inimitable"}],"multiple":false},{"enonce":"Remets dans l’ordre un plan de dissertation sur la question « par quoi l’art est-il défini ? »","aide":"Suis la progression du chapitre.","type":"ordre","items":[{"id":"a","texte":"L’art était défini comme imitation, jusqu’à la photographie"},{"id":"b","texte":"Danto, Dickie, Benjamin et Adorno proposent des réponses"},{"id":"c","texte":"Une transgression devenue canonique reste-t-elle une transgression ?"},{"id":"d","texte":"Duchamp déplace la question : le choix et le contexte font l’œuvre"}]}]}$ex$::jsonb,
