  ('7cbd8a7e-3772-51db-a89c-0390e1c6eb36'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Se raconter devant les autres","competence":"analyser-texte","situation":"Un passage adapté de Rousseau ouvre une autobiographie. Relève à qui il s’adresse, associe auteurs et œuvres, puis trie deux manières de se connaître.","documents":[{"id":"conf","type":"texte","genre":"source","titre":"Une entreprise sans exemple","blocs":["Je forme une entreprise qui n’a pas d’exemple. Je veux montrer à mes semblables un homme dans toute la vérité de sa nature, et cet homme, ce sera moi."],"source":"D’après Rousseau, *Les Confessions* (publiées en 1782 et 1789) — texte adapté"}],"questions":[{"enonce":"Touche le mot qui désigne ceux à qui l’auteur s’adresse.","aide":"Il s’adresse à ceux qui lui ressemblent, pas à Dieu.","type":"zone","document":"conf","multiple":false},{"enonce":"Associe chaque auteur à son œuvre.","aide":"Un Père de l’Église, deux philosophes des Lumières et de la Renaissance, un médecin.","type":"association","gauche":[{"id":"g0","texte":"Saint Augustin"},{"id":"g1","texte":"Rousseau"},{"id":"g2","texte":"Montaigne"},{"id":"g3","texte":"Freud"}],"droite":[{"id":"d0","texte":"Émile ou De l’éducation, en 1762"},{"id":"d1","texte":"Les Essais"},{"id":"d2","texte":"Les Confessions, au IVe siècle"},{"id":"d3","texte":"L’Interprétation du rêve, en 1900"}]},{"enonce":"Range chaque affirmation du côté de l’introspection classique ou de Freud.","aide":"Un camp fait confiance au regard intérieur, l’autre le juge insuffisant.","type":"categories","categories":[{"id":"c0","texte":"Introspection classique"},{"id":"c1","texte":"Freud"}],"items":[{"id":"i0","texte":"Le moi n’est pas maître dans sa propre maison"},{"id":"i1","texte":"Regarder en soi suffit pour se connaître"},{"id":"i2","texte":"La conscience s’atteint directement"},{"id":"i3","texte":"Il faut passer par les rêves et les actes manqués"}]}]}$ex$::jsonb,
