   $ex${"titre":"Le nom qu’on oublie","competence":"analyser-document","situation":"Le journal imaginaire de Clara note deux faits étranges. Interprète-les avec Freud, puis complète la formule sur le moi.","documents":[{"id":"jrnl","type":"texte","genre":"lettre","titre":"Journal de Clara","blocs":["Mardi. J’ai oublié le prénom de ma cousine au moment de la présenter, alors que je le connais depuis toujours. Je n’ai pas compris pourquoi.","Jeudi. J’ai rêvé de la maison de mon enfance, avec une porte que je n’osais pas ouvrir. Au réveil, j’étais inquiète sans savoir de quoi."],"source":"Journal imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui signale un acte manqué dans le journal de Clara.","aide":"Un acte manqué est une défaillance en apparence banale.","type":"zone","document":"jrnl","multiple":false},{"enonce":"Que retiendrait Freud de ces deux notes ?","aide":"Freud ne renonce pas à se connaître : il change de méthode.","type":"choix","options":[{"id":"a","texte":"Le moi n’a aucun rapport avec ce que rêve Clara"},{"id":"b","texte":"Le moi se connaît directement en se regardant lui-même"},{"id":"c","texte":"Le moi produit des traces que l’on peut interpréter"},{"id":"d","texte":"Le moi devrait s’interdire de rêver pour rester clair"}],"multiple":false},{"enonce":"Complète la formule de Freud.","aide":"Freud parle d’une demeure.","type":"trous","segments":["Le moi n’est pas ",0," dans sa propre ",1,"."],"banque":["juge","maison","ville","maître"]},{"enonce":"Remets dans l’ordre la démarche qui se dessine à partir du journal.","aide":"Partir des traces, pas d’une certitude.","type":"ordre","items":[{"id":"a","texte":"Elle cherche ce que ces traces disent d’elle"},{"id":"b","texte":"Elle constate qu’elle ne comprend pas ce qui s’est passé"},{"id":"c","texte":"Elle en tire une connaissance de soi plus juste"},{"id":"d","texte":"Clara note un oubli et un rêve étranges"}]}]}$ex$::jsonb,
