   $ex${"titre":"Le regard de l’autre","competence":"raisonner","situation":"Deux amis imaginaires disent chacun ce que l’autre fait au moi. Relie leurs phrases à Hegel et à Sartre, puis interroge la formule « se raconter, c’est se construire ».","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Deux façons de parler d’autrui","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Louise","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sam","texte":"Je ne sais vraiment qui je suis que lorsque tu me reconnais."},{"qui":"Louise","texte":"Moi, quand tu me regardes, je me sens figée comme un objet."}]},{"id":"rap","type":"tableau","titre":"Ce que l’autre fait au moi","colonnes":["","Hegel","Sartre"],"lignes":[["Le rôle d’autrui","Il me reconnaît : c’est ainsi que j’ai conscience de moi","Son regard me fige en objet"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque réplique au penseur qui l’inspire.","aide":"Reconnaissance d’un côté, regard qui fige de l’autre.","type":"association","gauche":[{"id":"g0","texte":"Sam : je me connais quand tu me reconnais"},{"id":"g1","texte":"Louise : ton regard me fige en objet"}],"droite":[{"id":"d0","texte":"Sartre"},{"id":"d1","texte":"Hegel"}]},{"enonce":"Qu’ont en commun Hegel et Sartre dans ces répliques ?","aide":"Dans les deux cas, autrui joue un rôle constitutif.","type":"choix","options":[{"id":"a","texte":"Le moi est une substance stable, indépendante de tout regard"},{"id":"b","texte":"Le moi est un rapport : il n’existe pas avant la relation à autrui"},{"id":"c","texte":"Le moi est une illusion qu’il faut dissoudre en se taisant"},{"id":"d","texte":"Le moi se forme seul, puis rencontre les autres après coup"}],"multiple":false},{"enonce":"Range chaque argument : le récit « dit » le moi, ou le « fabrique » ?","aide":"Sélectionner et justifier, c’est construire.","type":"categories","categories":[{"id":"c0","texte":"Il dit le moi"},{"id":"c1","texte":"Il fabrique le moi"}],"items":[