   $ex${"titre":"Perdre du temps pour en gagner","competence":"raisonner","situation":"Un texte adapté de Rousseau défend l’éducation négative. Applique-le à deux situations, puis complète le dilemme que Kant en tire.","documents":[{"id":"rou","type":"texte","genre":"source","titre":"Ne pas gagner de temps","blocs":["Le plus utile de toute l’éducation n’est pas de gagner du temps, mais d’en perdre. Protège le cœur de l’enfant des préjugés : laisse-le apprendre par l’expérience et par la nécessité des choses, non par l’autorité du maître."],"source":"D’après Rousseau, *Émile ou De l’éducation* (1762) — texte adapté"},{"id":"neg","type":"tableau","titre":"Deux attitudes d’éducateur","colonnes":["","Éducation négative","Éducation autoritaire"],"lignes":[["Moyen","L’expérience et la nécessité des choses","Le discours et l’autorité du maître"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne la voie par laquelle l’enfant apprend selon Rousseau.","aide":"Cherche ce qui s’oppose à l’autorité du maître.","type":"zone","document":"rou","multiple":false},{"enonce":"Range chaque situation du côté de l’éducation négative ou autoritaire.","aide":"Éprouver par soi-même, ou obéir à un ordre ?","type":"categories","categories":[{"id":"c0","texte":"Éducation négative"},{"id":"c1","texte":"Éducation autoritaire"}],"items":[{"id":"i0","texte":"Un maître laisse l’élève se tromper avant de discuter"},{"id":"i1","texte":"Un père fait recopier cent fois une règle sans l’expliquer"},{"id":"i2","texte":"Lina laisse son frère sortir sans écharpe : il a froid et comprend"},{"id":"i3","texte":"Une tante impose une leçon et punit celui qui hésite"}]},{"enonce":"Complète le dilemme de Kant.","aide":"C’est la tension de toute éducation.","type":"trous","segments":["Comment cultiver la ",0," par la ",1," ?"],"banque":["mémoire","contrainte","liberté","raison"]}]}$ex$::jsonb,
