   $ex${"titre":"Quatre siècles d’école","competence":"se-reperer-temps","situation":"Place sur une frise les grandes étapes du chapitre, puis rapproche les critiques de l’école et la réponse d’Arendt.","documents":[{"id":"fr","type":"frise","titre":"Jalons de la pensée de l’éducation","debut":1750,"fin":2000,"pas":50,"evenements":[{"id":"z1","date":1762,"nom":"Émile"},{"id":"z2","date":1792,"nom":"Condorcet"},{"id":"z3","date":1881,"nom":"Lois Ferry"},{"id":"z4","date":1964,"nom":"Les Héritiers"},{"id":"z5","date":1971,"nom":"Société sans école"}]},{"id":"ar","type":"texte","genre":"source","titre":"Transmettre et renouveler","blocs":["C’est parce que le monde est ancien qu’on doit l’enseigner aux enfants. Et c’est parce qu’il est confié à des nouveaux venus qu’il peut être renouvelé."],"source":"D’après Hannah Arendt, *La Crise de la culture* — texte adapté"}],"questions":[{"enonce":"Touche le jalon qui rend l’école gratuite, laïque et obligatoire.","aide":"Il date de la fin du XIXe siècle.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent *Les Héritiers* d’*Une société sans école* ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Range chaque idée du côté de son auteur.","aide":"Un sociologue du capital culturel, un critique de l’institution, un pédagogue des opprimés.","type":"categories","categories":[{"id":"c0","texte":"Bourdieu et Passeron"},{"id":"c1","texte":"Illich"},{"id":"c2","texte":"Freire"}],"items":[{"id":"i0","texte":"Une institution qui crée le besoin qu’elle prétend satisfaire"},{"id":"i1","texte":"La méritocratie apparente de l’école"},{"id":"i2","texte":"Un maître qui dépose le savoir, un élève qui le reçoit"},{"id":"i3","texte":"Une éducation « bancaire » à remplacer par la conscientisation"},{"id":"i4","texte":"Un capital culturel qui avantage ceux qui l’ont déjà"}]},{"enonce":"Touche le mot qui dit ce que permet d’attendre l’arrivée des nouveaux venus.","aide":"Le mot s’oppose à « ancien ».","type":"zone","document":"ar","multiple":false},{"enonce":"Que retient Arendt de la tension entre transmettre et renouveler ?","aide":"Le texte donne deux raisons qui se complètent.","type":"choix","options":[{"id":"a","texte":"Il ne faut pas choisir : on transmet un monde qu’on peut renouveler"},{"id":"b","texte":"Il faut choisir la transmission seule, le renouvellement étant dangereux"},{"id":"c","texte":"Il faut attendre que le monde change pour décider de l’enseigner"},{"id":"d","texte":"Il faut choisir le renouvellement seul, la transmission étant inutile"}],"multiple":false}]}$ex$::jsonb,
