  ('70da3aef-6b9c-5d46-a2e1-f4414de341b7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Theuth et le roi Thamous","competence":"analyser-texte","situation":"Dans un passage adapté du Phèdre, un dieu propose l’écriture à un roi. Relève le mot de chaque personnage, puis rapproche sa crainte d’une inquiétude d’aujourd’hui.","documents":[{"id":"phe","type":"texte","genre":"source","titre":"Le mythe de Theuth","blocs":["Theuth, le dieu inventeur, présente l’écriture au roi Thamous : « Elle rendra les Égyptiens plus savants : c’est le remède de la mémoire. » Le roi répond : « Elle produira l’oubli dans les âmes : les hommes croiront savoir sans rien savoir. »"],"source":"D’après Platon, *Phèdre* — texte adapté"}],"questions":[{"enonce":"Touche le mot par lequel Theuth défend l’écriture.","aide":"Theuth la présente comme un secours pour la mémoire.","type":"zone","document":"phe","multiple":false},{"enonce":"Touche le mot qui résume la crainte du roi.","aide":"Thamous redoute l’effet contraire de la mémoire.","type":"zone","document":"phe","multiple":false},{"enonce":"Quelle plainte d’aujourd’hui ressemble à celle de Thamous ?","aide":"Thamous craint que le support nouveau ruine la mémoire.","type":"choix","options":[{"id":"a","texte":"« Avec le téléphone, plus personne ne retient rien par cœur. »"},{"id":"b","texte":"« Avec le téléphone, plus personne ne sait écrire un mot. »"},{"id":"c","texte":"« Avec le téléphone, tout le monde retient trop de choses. »"},{"id":"d","texte":"« Avec le téléphone, les livres n’ont jamais existé. »"}],"multiple":false}]}$ex$::jsonb,
