  ('70da3aef-6b9c-5d46-a2e1-f4414de341b7'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Gestes, habitudes, souvenirs","competence":"analyser-document","situation":"Un atelier imaginaire sert de fil rouge : on y transmet bien autre chose que des contenus. Trie les situations selon ce qui passe et comment.","documents":[{"id":"atel","type":"texte","genre":"recit","titre":"À l’atelier de menuiserie","blocs":["Élias apprend à affûter un ciseau en regardant sa maîtresse, puis en l’imitant. Chez lui, on parle d’une certaine façon et l’on se tient à table sans jamais l’avoir appris. Sur la place du village, la commémoration du 11 novembre rappelle chaque année ce que le village choisit de retenir."],"source":"Récit imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque situation dans le mode de transmission qu’elle illustre.","aide":"Faire en regardant, hériter sans apprendre, se souvenir ensemble.","type":"categories","categories":[{"id":"c0","texte":"Gestes par imitation"},{"id":"c1","texte":"Habitus familial"},{"id":"c2","texte":"Mémoire collective"}],"items":[{"id":"i0","texte":"Se tenir à table sans l’avoir appris"},{"id":"i1","texte":"Affûter un ciseau en imitant sa maîtresse"},{"id":"i2","texte":"Apprendre un tour de main dans un compagnonnage"},{"id":"i3","texte":"Commémorer le 11 novembre sur la place"},{"id":"i4","texte":"Parler à la maison d’une certaine façon"}]},{"enonce":"Associe chaque notion à son auteur.","aide":"Un sociologue de l’école, un sociologue de la mémoire, un philosophe du numérique.","type":"association","gauche":[{"id":"g0","texte":"Habitus"},{"id":"g1","texte":"Cadres sociaux de la mémoire"},{"id":"g2","texte":"Petite Poucette"}],"droite":[{"id":"d0","texte":"Halbwachs"},{"id":"d1","texte":"Bourdieu"},{"id":"d2","texte":"Michel Serres"}]},{"enonce":"Que montre la commémoration du 11 novembre de ce récit ?","aide":"Commémorer, c’est choisir ce qu’on retient.","type":"choix","options":[{"id":"a","texte":"Une société transmet uniquement la vérité telle qu’elle fut vécue"},{"id":"b","texte":"Une société transmet exclusivement des savoir-faire techniques"},{"id":"c","texte":"Une société transmet des règles de grammaire aux enfants"},{"id":"d","texte":"Une société transmet aussi, en creux, ce qu’elle choisit d’oublier"}],"multiple":false}]}$ex$::jsonb,
