   $ex${"titre":"Transmettre, c’est trahir un peu","competence":"raisonner","situation":"Une frise de supports, un passage adapté de Michel Serres et un proverbe : croise-les pour comprendre pourquoi une tradition doit se réinterpréter.","documents":[{"id":"ser","type":"texte","genre":"source","titre":"Petite Poucette","blocs":["Le savoir est désormais devant elle, accessible partout et tout de suite. Il ne s’agit donc plus de lui remplir la tête, mais de lui apprendre à s’orienter dans ce qui existe déjà."],"source":"D’après Michel Serres, *Petite Poucette* (2012) — texte adapté"},{"id":"fr","type":"frise","titre":"Des supports du savoir","debut":1400,"fin":2020,"pas":100,"evenements":[{"id":"z1","date":1450,"nom":"Imprimerie"},{"id":"z2","date":2012,"nom":"Petite Poucette"}]}],"questions":[{"enonce":"Touche le verbe qui résume ce que l’école doit désormais apprendre à Petite Poucette.","aide":"Il n’est plus question de remplir, mais de se repérer.","type":"zone","document":"ser","multiple":false},{"enonce":"Range ces trois moments de la transmission, du plus ancien au plus récent.","aide":"Antiquité, Renaissance, XXIe siècle.","type":"ordre","items":[{"id":"a","texte":"L’imprimerie de Gutenberg, vers 1450"},{"id":"b","texte":"Petite Poucette de Michel Serres, en 2012"},{"id":"c","texte":"Le mythe de Theuth dans le Phèdre de Platon"}]},{"enonce":"Quel exercice illustre le mieux la leçon de Michel Serres ?","aide":"Il ne s’agit plus de mémoriser, mais de se repérer.","type":"choix","options":[{"id":"a","texte":"Recopier cent fois la liste des fleuves avant de la réciter sans erreur"},{"id":"b","texte":"Comparer trois sources en ligne sur un même sujet pour en vérifier la fiabilité"},{"id":"c","texte":"Interdire le numérique en classe pour préserver la mémoire des élèves"},{"id":"d","texte":"Distribuer un polycopié que chacun doit apprendre mot à mot"}],"multiple":false},{"enonce":"Complète le proverbe italien.","aide":"La transmission est une traduction.","type":"trous","segments":["*Traduttore, ",0,"* : traduire, c’est ",1," un peu."],"banque":["créer","copier","trahir","traditore"]}]}$ex$::jsonb,
