  ('7aeefedb-4028-5b71-b194-3542de89aaef'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Sortir de la minorité","competence":"analyser-texte","situation":"Un passage adapté de Kant définit les Lumières. Relève ce qui maintient l’homme en minorité, distingue les mots clés, puis rends-les à leur sens.","documents":[{"id":"ka","type":"texte","genre":"source","titre":"Qu’est-ce que les Lumières ?","blocs":["La minorité est l’incapacité de se servir de son entendement sans la direction d’autrui. L’homme en est lui-même responsable, quand la cause en est non dans un défaut d’entendement, mais dans la paresse et la lâcheté. Aie le courage de te servir de ton propre entendement : telle est la devise des Lumières."],"source":"D’après Kant, *Qu’est-ce que les Lumières ?* (1784) — texte adapté"}],"questions":[{"enonce":"Touche les deux mots qui expliquent pourquoi l’homme reste en minorité.","aide":"Ce sont deux défauts de caractère, pas un manque d’intelligence.","type":"zone","document":"ka","multiple":true},{"enonce":"Associe chaque mot à son sens dans le texte.","aide":"Lis chaque mot dans la phrase où il apparaît.","type":"association","gauche":[{"id":"g0","texte":"Minorité"},{"id":"g1","texte":"Responsable"},{"id":"g2","texte":"Sapere aude"}],"droite":[{"id":"d0","texte":"Ce n’est pas la nature qui nous y maintient"},{"id":"d1","texte":"Incapacité de penser sans la direction d’autrui"},{"id":"d2","texte":"Ose savoir, aie le courage de penser"}]},{"enonce":"Pour Kant, qui est responsable de la minorité ?","aide":"Kant exclut le manque d’entendement.","type":"choix","options":[{"id":"a","texte":"Celui qui manque de courage pour penser par lui-même"},{"id":"b","texte":"Celui qui vit sous l’autorité d’un maître sévère"},{"id":"c","texte":"Celui qui a mal reçu son éducation pendant l’enfance"},{"id":"d","texte":"Celui que la nature a privé de toute intelligence"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m36","m39"]},"explication":"Ce sont **paresse** et **lâcheté** : la nature ne nous maintient pas en minorité, nous le sommes par manque de courage."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Minorité** : dépendre de la direction d’autrui ; **responsable** : la cause est en nous ; ***Sapere aude*** : ose savoir."},{"cle":{"type":"choix","ids":["a"]},"explication":"La cause est la **paresse et la lâcheté**, non un défaut d’entendement : l’homme est donc responsable."}]$ex$::jsonb),
