   $ex${"titre":"Des libertés qui ont mis du temps","competence":"se-reperer-temps","situation":"Sur une frise, suis quelques émancipations politiques et leurs reculs, puis mesure les délais avant de conclure.","documents":[{"id":"fr","type":"frise","titre":"Émancipations en France","debut":1780,"fin":1970,"pas":10,"evenements":[{"id":"z1","date":1791,"nom":"Juifs émancipés"},{"id":"z2","date":1794,"nom":"Abolition esclavage"},{"id":"z3","date":1802,"nom":"Esclavage rétabli"},{"id":"z4","date":1848,"nom":"Abolition définitive"},{"id":"z5","date":1944,"nom":"Vote des femmes"},{"id":"z6","date":1965,"nom":"Travail sans accord"}]}],"questions":[{"enonce":"Touche l’événement qui montre qu’une émancipation peut être remise en cause.","aide":"Il suit de près une abolition.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent la première abolition de l’esclavage de l’abolition définitive ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Combien d’années séparent le vote des femmes de la loi qui leur permet de travailler et d’ouvrir un compte sans l’accord de leur mari ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Que conclure de cette frise ?","aide":"Regarde les écarts et le retour de 1802.","type":"choix","options":[{"id":"a","texte":"Une liberté proclamée ne peut jamais être remise en cause"},{"id":"b","texte":"Une liberté proclamée concerne toujours tous les citoyens à la fois"},{"id":"c","texte":"Une liberté proclamée devient réelle le jour même de son vote"},{"id":"d","texte":"Une liberté proclamée ne devient réelle qu’au prix de longs délais"}],"multiple":false}]}$ex$::jsonb,
