  ('7aeefedb-4028-5b71-b194-3542de89aaef'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le maître qui explique","competence":"argumenter","situation":"Un texte adapté de Rancière confronte deux figures de maître. Trie leurs effets, relève la tension, puis complète la problématique de l’essai.","documents":[{"id":"ran","type":"texte","genre":"source","titre":"Le maître ignorant","blocs":["Jacotot fait une hypothèse : les intelligences sont égales. Il ne faut pas réduire une inégalité, il faut poser l’égalité au départ et la vérifier. Celui qui explique installe la dépendance qu’il prétend guérir."],"source":"D’après Jacques Rancière, *Le Maître ignorant* (1987) — texte adapté"},{"id":"ten","type":"tableau","titre":"L’école obligatoire et la laïcité","colonnes":["","Elle libère","Elle impose"],"lignes":[["L’école obligatoire","De l’ignorance et du travail des enfants","Elle arrache l’enfant à sa famille"],["La laïcité","Du dogme","Sa propre norme"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui résume l’hypothèse de départ de Jacotot.","aide":"C’est un adjectif appliqué aux intelligences.","type":"zone","document":"ran","multiple":false},{"enonce":"Range chaque trait du côté du maître qui explique ou du maître ignorant.","aide":"L’un suppose l’inégalité, l’autre l’égalité.","type":"categories","categories":[{"id":"c0","texte":"Maître qui explique"},{"id":"c1","texte":"Maître ignorant"}],"items":[{"id":"i0","texte":"Il laisse l’élève vérifier sa propre capacité"},{"id":"i1","texte":"Il pose l’égalité des intelligences au départ"},{"id":"i2","texte":"Il installe la dépendance qu’il prétend guérir"},{"id":"i3","texte":"Il suppose que l’élève ne comprendra pas seul"}]},{"enonce":"Que montre le tableau de l’école obligatoire et de la laïcité ?","aide":"Chaque ligne comporte deux colonnes.","type":"choix","options":[{"id":"a","texte":"Une émancipation libère de quelque chose mais impose aussi sa propre norme"},{"id":"b","texte":"Une émancipation libère de tout sans jamais rien imposer à personne"},{"id":"c","texte":"Une émancipation n’a jamais d’effet réel sur la vie des enfants"},{"id":"d","texte":"Une émancipation impose toujours plus qu’elle ne libère"}],"multiple":false},{"enonce":"Complète la problématique de l’essai.","aide":"C’est la tension du chapitre.","type":"trous","segments":["L’éducation émancipe-t-elle, ou fabrique-t-elle la ",0," qu’elle prétend ",1," ?"],"banque":["minorité","liberté","confirmer","abolir"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"Le mot est **égales** : l’égalité des intelligences est posée au départ."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le **maître qui explique** suppose l’inégalité et crée la dépendance ; le **maître ignorant** pose l’égalité et la vérifie."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Il n’y a pas d’émancipation qui ne s’exerce depuis quelque part** : elle libère et impose à la fois."},{"cle":{"type":"trous","trous":[["minorite"],["abolir"]]},"affichage":"minorité · abolir","explication":"L’éducation émancipe-t-elle, ou fabrique-t-elle la **minorité** qu’elle prétend **abolir** ?"}]$ex$::jsonb),
