   $ex${"titre":"Trois romans, trois dates","competence":"se-reperer-temps","situation":"Tu prépares une fiche sur les romans fondateurs de la dystopie. Place-les sur une frise, mesure un écart, puis associe chaque roman à son moyen de servitude.","documents":[{"id":"fr","type":"frise","titre":"Trois dystopies fondatrices","debut":1900,"fin":1960,"pas":10,"evenements":[{"id":"z1","date":1920,"nom":"Nous autres"},{"id":"z2","date":1932,"nom":"Meilleur des mondes"},{"id":"z3","date":1949,"nom":"1984"}]}],"questions":[{"enonce":"Touche le roman de Huxley sur la frise.","aide":"Il se place entre les deux autres romans.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent *Le Meilleur des mondes* de *1984* ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque roman à son moyen de servitude.","aide":"Transparence, plaisir, terreur.","type":"association","gauche":[{"id":"g0","texte":"Nous autres"},{"id":"g1","texte":"Le Meilleur des mondes"},{"id":"g2","texte":"1984"}],"droite":[{"id":"d0","texte":"Le plaisir, le conditionnement et le soma"},{"id":"d1","texte":"La terreur, Big Brother et la novlangue"},{"id":"d2","texte":"Les maisons de verre et l’ablation de l’imagination"}]}]}$ex$::jsonb,
