  ('4fce27b4-0ef0-58ec-b4f2-92b9f0286eea'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le ministère de la Clarté","competence":"analyser-document","situation":"Un communiqué imaginaire s’inspire de la novlangue. Repère ses procédés, trie les mécanismes d’une dystopie, puis oppose Huxley et Orwell.","documents":[{"id":"min","type":"texte","genre":"article","titre":"Note du ministère de la Clarté publique","blocs":["Le mot « grève » est remplacé par « pause collective ». Les anciens dictionnaires sont retirés : la nouvelle édition est la seule qui existe, et elle a toujours dit ce qu’elle dit aujourd’hui. Toute autre version du passé est une erreur de mémoire."],"source":"Note imaginaire, écrite pour l’exercice, inspirée de *1984*"}],"questions":[{"enonce":"Touche le mot qui adoucit le terme « grève » dans la note.","aide":"Cherche l’adjectif qui transforme le mot sans le nommer.","type":"zone","document":"min","multiple":false},{"enonce":"Range chaque procédé de la note dans le mécanisme qu’il illustre.","aide":"Un camp joue sur les mots, l’autre sur ce qu’on a vécu.","type":"categories","categories":[{"id":"c0","texte":"Appauvrir le vocabulaire"},{"id":"c1","texte":"Réécrire le passé"}],"items":[{"id":"i0","texte":"Remplacer « grève » par « pause collective »"},{"id":"i1","texte":"Affirmer que la nouvelle édition a toujours dit la même chose"},{"id":"i2","texte":"Retirer les anciens dictionnaires"},{"id":"i3","texte":"Supprimer un mot gênant du langage courant"}]},{"enonce":"Dans une ville imaginaire, on distribue gratuitement divertissements et pilules pour que personne ne songe à protester. Quel auteur aurait reconnu ce monde ?","aide":"Ici, pas de menace : on offre ce que les gens désirent.","type":"choix","options":[{"id":"a","texte":"Orwell, qui craint qu’on nous prive de liberté par la peur et l’interdiction"},{"id":"b","texte":"Huxley, qui craint qu’on nous prive de liberté en nous donnant ce que nous désirons"},{"id":"c","texte":"Zamiatine, qui craint qu’on nous prive de liberté en supprimant toute lumière"},{"id":"d","texte":"Arendt, qui craint qu’on nous prive de liberté en interdisant tout travail"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"Le mot est **collective** : la note change le vocabulaire pour rendre la revendication moins pensable."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Changer ou supprimer des mots **appauvrit** la langue ; retirer et contredire l’archive **réécrit** le passé."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est **Huxley** : la servitude passe par le **plaisir** et le conditionnement."}]$ex$::jsonb),
  ('4fce27b4-0ef0-58ec-b4f2-92b9f0286eea'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux avertissements, un même détour","competence":"argumenter","situation":"Un tableau compare Huxley et Orwell, et un texte adapté d’Arendt décrit le totalitarisme. Croise-les pour comprendre pourquoi la dystopie parle d’histoire.","documents":[{"id":"hx","type":"tableau","titre":"Deux avertissements","colonnes":["","Huxley","Orwell"],"lignes":[["Ce qu’il craint","Qu’on nous prive de liberté en nous donnant ce que nous désirons","Qu’on nous arrache la liberté par la peur"],["Le résumé de Postman","Que personne n’ait plus envie de lire","Que les livres soient interdits"]],"enteteLignes":true},{"id":"ar","type":"texte","genre":"source","titre":"Les trois piliers","blocs":["Le totalitarisme repose sur une idéologie totale qui prétend tout expliquer, sur la terreur qui brise toute résistance, et sur la destruction de l’espace public où les hommes se parlent."],"source":"D’après Hannah Arendt, *Les Origines du totalitarisme* (1951) — texte adapté"}],"questions":[{"enonce":"Touche le mot qui désigne la prétention du totalitarisme à tout expliquer.","aide":"Cherche le nom d’un système d’idées.","type":"zone","document":"ar","multiple":false},{"enonce":"Range chaque scénario du côté d’Huxley ou d’Orwell.","aide":"Plaisir contre peur.","type":"categories","categories":[{"id":"c0","texte":"Huxley"},{"id":"c1","texte":"Orwell"}],"items":[{"id":"i0","texte":"On conditionne chacun à aimer sa place dès l’enfance"},{"id":"i1","texte":"On surveille chaque parole avec un écran dans chaque pièce"},{"id":"i2","texte":"On interdit les livres et on punit ceux qui en possèdent"},{"id":"i3","texte":"On noie la population sous des divertissements sans fin"}]},{"enonce":"Pourquoi dit-on que les dystopies parlent de l’histoire plus que de l’avenir ?","aide":"Elles ne prédisent pas : elles décrivent des mécanismes.","type":"choix","options":[{"id":"a","texte":"Elles décrivent des événements qui se sont déjà tous produits"},{"id":"b","texte":"Elles décrivent des sociétés qui existeront sûrement un jour"},{"id":"c","texte":"Elles décrivent des mécanismes réels, nés des totalitarismes"},{"id":"d","texte":"Elles décrivent des lois que les régimes ont toutes abandonnées"}],"multiple":false},{"enonce":"Complète la formule.","aide":"La première espère, la seconde avertit.","type":"trous","segments":["L’utopie et la dystopie sont le même ",0," retourné : décrire une société ",1," organisée."],"banque":["partiellement","geste","mot","entièrement"]}]}$ex$::jsonb,
