  ('b7369998-f445-522b-a4aa-73ca33b02ec4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La cour de récréation sans surveillants","competence":"analyser-texte","situation":"Deux élèves imaginaires imaginent la cour sans surveillants. Reconnais Hobbes et Rousseau, relève un mot qui dit l’état de nature chez Hobbes, puis remonte aux causes de la violence.","documents":[{"id":"cour","type":"texte","genre":"recit","titre":"Un débat sur la cour","blocs":["Hugo : « Sans surveillants, la cour deviendrait un champ de bataille : chacun contre chacun. »","Jade : « Non, ce qui rend violent, c’est la compétition et la comparaison. La cour serait calme sans elles. »"],"source":"Débat imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot d’Hugo qui évoque la guerre de tous contre tous.","aide":"Cherche une image militaire.","type":"zone","document":"cour","multiple":false},{"enonce":"Associe chaque élève au penseur dont il s’inspire.","aide":"Un pouvoir fort, ou une société qui compare.","type":"association","gauche":[{"id":"g0","texte":"Hugo"},{"id":"g1","texte":"Jade"}],"droite":[{"id":"d0","texte":"Rousseau"},{"id":"d1","texte":"Hobbes"}]},{"enonce":"Selon Rousseau, qu’est-ce qui produit la violence humaine ?","aide":"Rousseau ne cherche pas la cause dans la nature de l’homme.","type":"choix","options":[{"id":"a","texte":"Les lois que le peuple s’est lui-même données"},{"id":"b","texte":"Les enfants que l’on n’a jamais laissés jouer librement"},{"id":"c","texte":"Les peuples qui n’ont jamais eu de gouvernement du tout"},{"id":"d","texte":"Les sociétés fondées sur la propriété et la comparaison"}],"multiple":false}]}$ex$::jsonb,
