  ('b7369998-f445-522b-a4aa-73ca33b02ec4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois situations, trois violences","competence":"analyser-document","situation":"Trois situations imaginaires illustrent des violences différentes. Associe-les aux notions de Weber, de Bourdieu et de Galtung, puis évalue une précaution de méthode.","documents":[{"id":"sit","type":"texte","genre":"recit","titre":"Trois scènes","blocs":["**A.** Un policier arrête un voleur en flagrant délit, dans le cadre de la loi.","**B.** Des élèves de milieu modeste se jugent eux-mêmes « pas faits pour les études longues », et s’en excusent.","**C.** Dans une région sans puits, des enfants meurent de soif sans qu’aucun coup ne soit porté."],"source":"Scènes imaginaires, écrites pour l’exercice"}],"questions":[{"enonce":"Range chaque scène dans la notion qu’elle illustre.","aide":"Un monopole de l’État, une domination acceptée, une inégalité qui tue.","type":"categories","categories":[{"id":"c0","texte":"Violence légitime (Weber)"},{"id":"c1","texte":"Violence symbolique (Bourdieu)"},{"id":"c2","texte":"Violence structurelle (Galtung)"}],"items":[{"id":"i0","texte":"C. Des enfants meurent sans qu’un coup soit porté"},{"id":"i1","texte":"A. Le policier arrête le voleur"},{"id":"i2","texte":"B. Des élèves jugent leur sort naturel"}]},{"enonce":"Touche le verbe qui montre que les élèves acceptent le jugement porté sur eux.","aide":"Personne ne frappe : les victimes s’en accommodent elles-mêmes.","type":"zone","document":"sit","multiple":false},{"enonce":"Pourquoi manier ces notions avec précaution dans un essai ?","aide":"Élargir un mot peut l’affaiblir.","type":"choix","options":[{"id":"a","texte":"Si rien n’est violence, le mot devient trop précis"},{"id":"b","texte":"Si tout est violence, le mot ne distingue plus rien"},{"id":"c","texte":"Si la loi l’interdit, le mot est forcément juste"},{"id":"d","texte":"Si un auteur l’emploie, le mot devient inattaquable"}],"multiple":false},{"enonce":"Que désigne le monopole de la violence physique légitime chez Weber ?","aide":"Police, justice, armée.","type":"choix","options":[{"id":"a","texte":"Une caractéristique de l’État moderne sur un territoire"},{"id":"b","texte":"Un pouvoir que les marchés détiennent sur les salaires"},{"id":"c","texte":"Un droit que chaque citoyen exerce contre son voisin"},{"id":"d","texte":"Un privilège que l’Église garde sur les croyants"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1"}},"explication":"**A** : monopole de la violence légitime ; **B** : domination acceptée par ceux qui la subissent ; **C** : inégalité qui tue sans coup porté."},{"cle":{"type":"zone","ids":["m33"]},"explication":"Le verbe est **excusent** : la violence symbolique s’exerce avec la complicité tacite de ceux qui la subissent."},{"cle":{"type":"choix","ids":["b"]},"explication":"Ces notions **élargissent** le mot : si tout est violence, il ne distingue plus rien."},{"cle":{"type":"choix","ids":["a"]},"explication":"Pour **Weber**, l’État moderne revendique avec succès le **monopole de la violence physique légitime** sur un territoire."}]$ex$::jsonb),
  ('b7369998-f445-522b-a4aa-73ca33b02ec4'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le bouc émissaire de la classe","competence":"raisonner","situation":"Une histoire de classe imaginaire suit, étape après étape, le schéma de René Girard. Complète la chaîne, relève le moment du bouc émissaire, puis juge une lecture de Freud.","documents":[{"id":"hist","type":"texte","genre":"recit","titre":"Histoire de classe","blocs":["Deux élèves veulent la même place de délégué : chacun désire ce que l’autre désire. La rivalité s’installe, puis la tension gagne toute la classe. Un jour, tout le monde s’accorde pour accuser Sacha, qui n’avait rien fait et que l’on désigne comme responsable. La classe se sent alors soudée."],"source":"Histoire imaginaire, écrite pour l’exercice"},{"id":"gir","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Le désir mimétique"},{"id":"z2","texte":"La rivalité"},{"id":"z3","texte":"La crise"},{"id":"z4","texte":"?"},{"id":"z5","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le verbe qui correspond à la désignation du bouc émissaire.","aide":"Cherche ce que la classe fait de Sacha.","type":"zone","document":"hist","multiple":false},{"enonce":"Remets dans l’ordre les étapes du schéma de Girard, d’après l’histoire.","aide":"Désir, rivalité, crise, victime, unité.","type":"ordre","items":[{"id":"a","texte":"Tous accusent Sacha"},{"id":"b","texte":"La tension gagne toute la classe"},{"id":"c","texte":"La classe se sent soudée"},{"id":"d","texte":"La rivalité s’installe entre eux"},{"id":"e","texte":"Deux élèves désirent la même place"}]},{"enonce":"Quel couple d’étapes complète les deux « ? » de la chaîne ?","aide":"Après la crise, une victime est désignée ; ensuite, le groupe se refait.","type":"choix","options":[{"id":"a","texte":"La rivalité, puis le désir mimétique"},{"id":"b","texte":"L’unité restaurée, puis le bouc émissaire"},{"id":"c","texte":"Le sacrifice, puis la rivalité renouvelée"},{"id":"d","texte":"Le bouc émissaire, puis l’unité restaurée"}],"multiple":false},{"enonce":"Que dirait Freud de la violence dans cette classe ?","aide":"Freud parle de refoulement et de culpabilité.","type":"choix","options":[{"id":"a","texte":"La civilisation ignore l’agressivité, qui n’est qu’un accident de caractère"},{"id":"b","texte":"La civilisation provoque l’agressivité par excès de plaisir et de liberté"},{"id":"c","texte":"La civilisation obtient l’ordre par le refoulement de l’agressivité, qui peut ressurgir"},{"id":"d","texte":"La civilisation supprime entièrement l’agressivité grâce à l’éducation reçue"}],"multiple":false}]}$ex$::jsonb,
