   $ex${"titre":"Enfermer ensemble les pauvres et les fous","competence":"analyser-texte","situation":"Un passage adapté de Foucault décrit le grand renfermement. Relève le critère réel de l’enfermement, suis l’évolution du statut du fou, puis corrige une idée reçue.","documents":[{"id":"fou","type":"texte","genre":"source","titre":"Le grand renfermement","blocs":["En 1656, à Paris, on enferme ensemble pauvres, oisifs, libertins et insensés. Le critère n’est pas médical : c’est l’incapacité de travailler, un critère social et moral."],"source":"D’après Michel Foucault, *Histoire de la folie à l’âge classique* (1961) — texte adapté"}],"questions":[{"enonce":"Touche le mot qui donne le critère réel de l’enfermement.","aide":"Le critère est social et moral, pas médical.","type":"zone","document":"fou","multiple":false},{"enonce":"Range les trois âges de la folie selon le cours, du plus ancien au plus récent.","aide":"Il circule, il est enfermé, il est observé.","type":"ordre","items":[{"id":"a","texte":"Le fou circule et parle, à la Renaissance"},{"id":"b","texte":"Le fou est observé par la psychiatrie naissante"},{"id":"c","texte":"Le fou est enfermé et tu, à partir de 1656"}]},{"enonce":"Que conclut-on du critère du grand renfermement ?","aide":"Le texte parle de critère social et moral.","type":"choix","options":[{"id":"a","texte":"L’enfermement relevait d’un progrès médical, sans lien avec la société"},{"id":"b","texte":"L’enfermement relevait d’un partage social et moral, non d’une médecine"},{"id":"c","texte":"L’enfermement relevait d’un geste religieux, sans lien avec le travail"},{"id":"d","texte":"L’enfermement relevait d’un choix des familles, sans lien avec l’État"}],"multiple":false}]}$ex$::jsonb,
