  ('a80fab3b-809c-5553-99d8-aa651fc764ae'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les chaînes tombent, le regard reste","competence":"raisonner","situation":"Une reconstitution imaginaire d’un asile rejoue la relecture foucaldienne de Pinel. Trie ce qu’on retire et ce qu’on installe, puis interprète.","documents":[{"id":"asile","type":"texte","genre":"recit","titre":"Dans un asile imaginaire","blocs":["On retire les chaînes des malades. Chaque matin, le médecin passe dans les salles, observe, note et juge la conduite de chacun. Les malades savent qu’on les regarde et apprennent à se surveiller eux-mêmes."],"source":"Scène imaginaire, écrite pour l’exercice, inspirée de la lecture de Pinel par Foucault"},{"id":"rel","type":"tableau","titre":"Deux lectures du geste de Pinel","colonnes":["","Image d’Épinal","Lecture de Foucault"],"lignes":[["Le geste","Une libération pure et simple","Une contrainte visible remplacée par une contrainte intériorisée"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe qui désigne le nouveau pouvoir du médecin.","aide":"Il ne s’agit plus de contraindre par la force, mais de regarder.","type":"zone","document":"asile","multiple":false},{"enonce":"Range chaque élément : ce qu’on retire, ou ce qu’on installe ?","aide":"Un camp disparaît du décor, l’autre s’y installe.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’on retire"},{"id":"c1","texte":"Ce qu’on installe"}],"items":[{"id":"i0","texte":"Les chaînes"},{"id":"i1","texte":"Le regard médical permanent"},{"id":"i2","texte":"Le jugement moral sur la conduite"},{"id":"i3","texte":"La violence physique visible"}]},{"enonce":"Comment Foucault relit-il le geste de Pinel ?","aide":"Regarde la seconde colonne du tableau.","type":"choix","options":[{"id":"a","texte":"Comme l’échec d’une médecine qui ne savait encore rien guérir"},{"id":"b","texte":"Comme la libération complète des malades enfin rendus à eux-mêmes"},{"id":"c","texte":"Comme le remplacement d’une contrainte visible par une contrainte intériorisée"},{"id":"d","texte":"Comme une simple légende qui n’aurait jamais eu aucun fondement"}],"multiple":false}]}$ex$::jsonb,
