   $ex${"titre":"Du grand renfermement au biopouvoir","competence":"argumenter","situation":"Un tableau d’œuvres et un tableau de critiques permettent de suivre la méthode de Foucault et ses limites.","documents":[{"id":"oeu","type":"tableau","titre":"Quatre œuvres de Foucault","colonnes":["Œuvre","Année","Ce qu’elle ajoute"],"lignes":[["*Naissance de la clinique*","1963","Le regard médical comme savoir-pouvoir"],["*Surveiller et punir*","1975","La discipline, le panoptique"],["*La Volonté de savoir*","1976","Le biopouvoir"]],"enteteLignes":true},{"id":"crit","type":"tableau","titre":"Deux critiques","colonnes":["Objection","Qui la porte"],"lignes":[["La chronologie du « grand renfermement » est contestable","Gauchet et Swain, Scull"],["On ne peut faire l’histoire de la folie dans le langage de la raison","Derrida"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque œuvre à sa notion.","aide":"Regard, discipline, vie.","type":"association","gauche":[{"id":"g0","texte":"Naissance de la clinique"},{"id":"g1","texte":"Surveiller et punir"},{"id":"g2","texte":"La Volonté de savoir"}],"droite":[{"id":"d0","texte":"La discipline et le panoptique"},{"id":"d1","texte":"Le biopouvoir"},{"id":"d2","texte":"Le regard médical comme savoir-pouvoir"}]},{"enonce":"Combien d’années séparent l’*Histoire de la folie* (1961) de *Surveiller et punir* ?","aide":"Cherche la date de *Surveiller et punir* dans le tableau.","type":"nombre","unite":"ans"},{"enonce":"Range chaque objection du côté de son auteur.","aide":"Une objection d’historien, une objection de philosophe.","type":"categories","categories":[{"id":"c0","texte":"Gauchet et Swain, Scull"},{"id":"c1","texte":"Derrida"}],"items":[{"id":"i0","texte":"L’histoire de la folie se fait dans le langage de la raison"},{"id":"i1","texte":"La chronologie du renfermement est contestable"},{"id":"i2","texte":"La date de 1656 ne vaut pas pour toute l’Europe"}]},{"enonce":"Quel outil de méthode Foucault fournit-il pour un essai, malgré ces objections ?","aide":"Folie, délinquance, normalité : des découpages…","type":"choix","options":[{"id":"a","texte":"Ne jamais citer d’objection, car elle rend l’argument fragile"},{"id":"b","texte":"Ne jamais utiliser d’institution comme exemple, car elle déforme tout"},{"id":"c","texte":"Ne jamais employer de date précise, car elle est toujours contestée"},{"id":"d","texte":"Ne jamais tenir une catégorie pour naturelle, car elle est historique"}],"multiple":false}]}$ex$::jsonb,
