  ('640789de-a2ba-55f1-9cbc-47c8ff599ab1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que les générations futures ne peuvent pas dire","competence":"analyser-texte","situation":"Tu prépares un exposé sur la responsabilité devant la technique. Tu lis un court passage adapté, tu relèves deux mots clés et tu remets son raisonnement en ordre.","documents":[{"id":"jo","type":"texte","genre":"source","titre":"Un changement d’échelle","blocs":["La technique d’autrefois agissait sur le présent et sur le proche. La technique moderne atteint des générations qui ne sont pas encore nées et ne peuvent ni consentir ni protester. Il faut donc juger une action sur ce qu’elle laisse derrière elle, et pas seulement sur son résultat immédiat. Devant un enjeu irréversible, mieux vaut donner plus de poids au pronostic pessimiste."],"source":"D’après Hans Jonas, *Le Principe responsabilité* (1979) — texte adapté"}],"questions":[{"enonce":"Touche le mot qui désigne ceux qui ne peuvent ni consentir ni protester.","aide":"Ils ne sont pas encore nés.","type":"zone","document":"jo","multiple":false},{"enonce":"Touche le mot qui justifie de peser davantage le pronostic pessimiste.","aide":"Pense à ce qu’on ne peut pas réparer après coup.","type":"zone","document":"jo","multiple":false},{"enonce":"Remets dans l’ordre le raisonnement du texte.","aide":"Le texte compare d’abord l’avant et l’après, puis conclut.","type":"ordre","items":[{"id":"a","texte":"La technique ancienne agissait sur le présent et le proche"},{"id":"b","texte":"La technique moderne atteint des générations qui ne peuvent ni consentir ni protester"},{"id":"c","texte":"Devant l’irréversible, on pèse davantage le pronostic pessimiste"},{"id":"d","texte":"On juge donc une action sur ce qu’elle laisse derrière elle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"Le mot est **générations** : les effets de la technique moderne touchent des êtres qui ne peuvent rien dire."},{"cle":{"type":"zone","ids":["m54"]},"explication":"Le mot est **irréversible** : quand on ne peut pas revenir en arrière, on donne plus de poids au pire."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"Le texte **oppose l’ancienne et la nouvelle technique, en tire une règle de jugement, puis la précise pour l’irréversible**."}]$ex$::jsonb),
  ('640789de-a2ba-55f1-9cbc-47c8ff599ab1'::uuid, 2, 2, 10, 35, 3,
