  ('640789de-a2ba-55f1-9cbc-47c8ff599ab1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un fleuve, un regard, un monstre","competence":"argumenter","situation":"Pour l’essai, tu croises un passage adapté de Heidegger et une fiche sur *Frankenstein*. Tu dois en tirer la bonne formule de problématisation.","documents":[{"id":"he","type":"texte","genre":"source","titre":"Le regard de la technique","blocs":["Ce qui est en jeu n’est pas l’usage que l’on fait de la technique, mais le regard qu’elle impose au monde. Sous ce regard, le fleuve n’est plus un fleuve : il devient d’abord une réserve d’énergie disponible."],"source":"D’après Heidegger, la technique et l’arraisonnement — texte adapté"},{"id":"fk","type":"tableau","titre":"*Frankenstein* (1818)","colonnes":["L’idée reçue","Ce que dit le roman"],"lignes":[["Victor est puni d’avoir créé","Il est puni d’avoir abandonné sa créature"],["La technique est monstrueuse","Le refus d’en répondre est monstrueux"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que la technique impose, selon ce passage.","aide":"Le passage l’oppose à l’usage.","type":"zone","document":"he","multiple":false},{"enonce":"D’après ce passage, que faut-il conclure d’un bon usage des outils ?","aide":"Relis la phrase qui oppose « usage » et « regard ».","type":"choix","options":[{"id":"a","texte":"Il ne suffit pas à régler la question posée par la technique"},{"id":"b","texte":"Il rend le regard de la technique inoffensif partout"},{"id":"c","texte":"Il prouve que la technique est un simple outil neutre"},{"id":"d","texte":"Il règle entièrement la question posée par la technique"}],"multiple":false},{"enonce":"Associe chaque auteur ou œuvre à l’idée qu’il sert en essai.","aide":"Reprends ce que le cours dit de chacun.","type":"association","gauche":[{"id":"g0","texte":"Hans Jonas"},{"id":"g1","texte":"Heidegger"},{"id":"g2","texte":"*Frankenstein*"}],"droite":[{"id":"d0","texte":"L’abandon de la créature"},{"id":"d1","texte":"L’heuristique de la peur"},{"id":"d2","texte":"L’arraisonnement du monde"}]},{"enonce":"Quelle formule le roman de Mary Shelley permet-il de poser en essai ?","aide":"Regarde la colonne « Ce que dit le roman » du tableau.","type":"choix","options":[{"id":"a","texte":"« Jusqu’où la science peut-elle aller ? »"},{"id":"b","texte":"« Qui répondra de ce qui arrivera ? »"},{"id":"c","texte":"« Faut-il interdire toute expérience ? »"},{"id":"d","texte":"« Peut-on créer la vie de ses mains ? »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19"]},"explication":"Le mot est **regard** : la technique impose une manière de voir le monde, pas seulement un usage."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Il ne suffit pas** : le passage déplace la question de l’usage vers le regard."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Jonas : l’heuristique de la peur ; Heidegger : l’arraisonnement ; *Frankenstein* : l’abandon de la créature.**"},{"cle":{"type":"choix","ids":["b"]},"explication":"La question n’est pas « peut-on ? » mais « **qui répondra de ce qui arrivera ?** »."}]$ex$::jsonb),
