   $ex${"titre":"Nous n’avons jamais été séparés","competence":"analyser-texte","situation":"Tu croises un passage adapté sur l’Anthropocène et un tableau sur les accusations portées contre notre rapport à la nature.","documents":[{"id":"lt","type":"texte","genre":"source","titre":"Une séparation qui ne tient plus","blocs":["Quand l’activité humaine devient une force géologique, l’histoire des sociétés et l’histoire de la Terre ne peuvent plus être racontées à part. Nous croyions avoir dominé la nature : nous découvrons que nous n’en avons jamais été aussi peu séparés."],"source":"D’après Bruno Latour — texte adapté"},{"id":"ge","type":"tableau","titre":"Généalogie du problème","colonnes":["Accusation","Ce qu’elle vise"],"lignes":[["Lynn White","?"],["Modernité cartésienne","La nature réduite à un objet mesurable"],["Économie extractive","La nature réduite à une ressource"],["Descola","?"]],"enteteLignes":true}],"questions":[{"enonce":"Que devient la distinction entre histoire humaine et histoire naturelle ?","aide":"Relis la première phrase du passage.","type":"choix","options":[{"id":"a","texte":"Elle se renforce, puisque l’humain domine la Terre"},{"id":"b","texte":"Elle reste valable, puisque la nature est immuable"},{"id":"c","texte":"Elle ne tient plus, puisque l’humain pèse sur la Terre"},{"id":"d","texte":"Elle disparaît seulement dans les sociétés anciennes"}],"multiple":false},{"enonce":"Touche le mot qui dit que la séparation est démentie.","aide":"Cherche la fin de la dernière phrase.","type":"zone","document":"lt","multiple":false},{"enonce":"Complète les deux cases « ? » du tableau.","aide":"Pense à « soumettez la terre » et au titre de l’ouvrage de Descola.","type":"trous","segments":["Lynn White met en cause le récit ",0," de la domination ; Descola montre que le partage ",1," est une singularité occidentale."],"banque":["biblique","antique","nature-culture","ville-campagne"]},{"enonce":"Que montre ce tableau sur l’origine de la crise écologique ?","aide":"Compare les lignes entre elles.","type":"choix","options":[{"id":"a","texte":"Plusieurs regards ont réduit la nature à un objet ou à une ressource"},{"id":"b","texte":"La crise vient uniquement des choix économiques récents"},{"id":"c","texte":"Une seule cause suffit à expliquer toute la crise écologique"},{"id":"d","texte":"Tous les auteurs visent exactement la même accusation"}],"multiple":false}]}$ex$::jsonb,
