   $ex${"titre":"Dignité, prix et génome","competence":"argumenter","situation":"Un tableau résume les grands dossiers de la bioéthique, un passage adapté de Habermas donne l’argument contre la programmation d’un enfant. Croise-les.","documents":[{"id":"gd","type":"tableau","titre":"Les grands dossiers","colonnes":["Domaine","Question ouverte","Droit français"],"lignes":[["Début de vie","Quel statut pour l’embryon ?","IVG, PMA ; GPA interdite"],["Fin de vie","Jusqu’où accompagner ?","Sédation profonde et continue, pas d’euthanasie active"],["Génome","Modifier les cellules germinales ?","Moratoire international"]],"enteteLignes":true},{"id":"ha","type":"texte","genre":"source","titre":"Un enfant programmé","blocs":["Celui qui a été conçu selon un projet ne peut plus se considérer comme l’auteur unique de sa vie. Programmer un enfant rompt ainsi l’égalité entre les générations."],"source":"D’après Jürgen Habermas, *L’Avenir de la nature humaine* (2001) — texte adapté"}],"questions":[{"enonce":"Touche ce que le droit français refuse en fin de vie.","aide":"Cherche la ligne « Fin de vie ».","type":"zone","document":"gd","multiple":false},{"enonce":"Touche le mot qui dit ce que perd l’enfant programmé.","aide":"Il ne peut plus se voir comme l’… unique de sa vie.","type":"zone","document":"ha","multiple":false},{"enonce":"Associe chaque référence à l’idée qu’elle apporte en essai.","aide":"Reprends les sections « Origine » et « Dignité » du cours.","type":"association","gauche":[{"id":"g0","texte":"Kant"},{"id":"g1","texte":"Habermas"},{"id":"g2","texte":"Code de Nuremberg"}],"droite":[{"id":"d0","texte":"La programmation rompt l’égalité entre générations"},{"id":"d1","texte":"La personne a une dignité, non un prix"},{"id":"d2","texte":"Le consentement volontaire est essentiel"}]},{"enonce":"Pourquoi CRISPR-Cas9 a-t-il fait passer la question du laboratoire au débat public ?","aide":"Pense à sa facilité d’emploi.","type":"choix","options":[{"id":"a","texte":"Il a fait interdire l’édition génétique dans le monde entier"},{"id":"b","texte":"Il a rendu l’édition génétique simple et peu coûteuse"},{"id":"c","texte":"Il a prouvé que l’édition génétique était sans risque"},{"id":"d","texte":"Il a rendu l’édition génétique réservée à quelques équipes"}],"multiple":false}]}$ex$::jsonb,
