   $ex${"titre":"Détresse, âme belle, deuil","competence":"argumenter","situation":"Un passage adapté sur les deux manières de créer, un tableau sur les objections au romantisme : tu croises les deux pour construire une discussion.","documents":[{"id":"ni","type":"texte","genre":"source","titre":"Manque ou surabondance","blocs":["Il existe deux manières de créer : par détresse, parce qu’on souffre du monde tel qu’il est ; ou par surabondance, parce qu’on déborde de force. La première dit le manque, la seconde donne."],"source":"D’après Nietzsche — texte adapté"},{"id":"ob","type":"tableau","titre":"Les objections","colonnes":["Penseur","Son reproche"],"lignes":[["Hegel","L’« âme belle » préfère sa pureté à l’action"],["Nietzsche","?"],["La psychanalyse","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme le romantisme que le texte critique.","aide":"Il s’oppose à la surabondance.","type":"zone","document":"ni","multiple":false},{"enonce":"Complète le tableau : associe chaque penseur à son reproche.","aide":"Reprends ce que dit le passage pour Nietzsche.","type":"association","gauche":[{"id":"g0","texte":"Nietzsche"},{"id":"g1","texte":"La psychanalyse"},{"id":"g2","texte":"Hegel"}],"droite":[{"id":"d0","texte":"Une pureté préférée à l’action"},{"id":"d1","texte":"Un deuil impossible dont l’objet est inconnu"},{"id":"d2","texte":"Un romantisme de la détresse, face à l’art de la surabondance"}]},{"enonce":"Complète le nœud du romantisme.","aide":"Trois mots simples, dans l’ordre du cours.","type":"trous","segments":["Le romantisme lie l’exaltation du ",0,", la découverte du ",1," qui passe, et le sentiment que le ",2," ne répond pas."],"banque":["destin","moi","temps","monde"]},{"enonce":"Que reproche la psychanalyse au romantisme de la mélancolie ?","aide":"Relis la ligne « La psychanalyse » du cours.","type":"choix","options":[{"id":"a","texte":"D’y voir une profondeur alors que c’est un deuil impossible"},{"id":"b","texte":"D’y voir une action alors que c’est une pure contemplation"},{"id":"c","texte":"D’y voir un deuil alors que c’est une profondeur réelle"},{"id":"d","texte":"D’y voir un jugement faux alors que c’est une vraie raison"}],"multiple":false}]}$ex$::jsonb,
