   $ex${"titre":"La tempête de Maya","competence":"argumenter","situation":"Une scène imaginée et une phrase adaptée de Kant : tu repères les deux temps du sublime, puis tu en tires le paradoxe du goût.","documents":[{"id":"ta","type":"texte","genre":"recit","titre":"Sur la falaise","blocs":["Sur la falaise, Maya regarde la tempête. La mer démesurée l’effraie d’abord ; puis elle se sent grandie de pouvoir penser cette puissance."],"source":"Scène imaginée pour l’exercice"},{"id":"ka","type":"texte","genre":"source","titre":"Dire « c’est beau »","blocs":["Quand je dis « c’est beau », je ne dis pas « cela me plaît ». J’attends que chacun en convienne, bien que je ne puisse pas le prouver."],"source":"D’après Kant, *Critique de la faculté de juger* — texte adapté"}],"questions":[{"enonce":"Touche le mot qui marque le déplaisir.","aide":"C’est le premier temps.","type":"zone","document":"ta","multiple":false},{"enonce":"Touche le mot qui marque la grandeur.","aide":"C’est le second temps.","type":"zone","document":"ta","multiple":false},{"enonce":"Pourquoi la scène relève-t-elle du sublime plutôt que du beau ?","aide":"Le beau apaise, le sublime excède.","type":"choix","options":[{"id":"a","texte":"La tempête offre une forme harmonieuse et apaisante"},{"id":"b","texte":"La tempête ne provoque aucun sentiment chez Maya"},{"id":"c","texte":"La tempête s’accorde parfaitement à nos facultés"},{"id":"d","texte":"La tempête excède ce que l’imagination peut saisir"}],"multiple":false},{"enonce":"Que montre la phrase adaptée de Kant ?","aide":"« C’est beau » n’est pas « cela me plaît ».","type":"choix","options":[{"id":"a","texte":"Le jugement esthétique est subjectif mais prétend à l’universalité"},{"id":"b","texte":"Le jugement esthétique ne concerne que l’artiste lui-même"},{"id":"c","texte":"Le jugement esthétique est une simple affaire de calcul"},{"id":"d","texte":"Le jugement esthétique est objectif et purement privé"}],"multiple":false}]}$ex$::jsonb,
