   $ex${"titre":"Du supplice à la surveillance","competence":"analyser-texte","situation":"Un passage adapté de Foucault sur la prison moderne. Tu le lis, tu classes ses idées et tu expliques le panoptique.","documents":[{"id":"fo","type":"texte","genre":"source","titre":"La peine déplacée","blocs":["Autrefois la peine visait le corps : l’échafaud donnait un spectacle. Aujourd’hui la prison vise l’âme, par l’emploi du temps et la surveillance continue. Dans le panoptique, le détenu sait qu’il peut être vu sans savoir quand : il finit par se surveiller lui-même."],"source":"D’après Foucault, *Surveiller et punir* (1975) — texte adapté"}],"questions":[{"enonce":"Touche le verbe qui dit ce que fait le détenu de lui-même.","aide":"Le pouvoir devient intérieur.","type":"zone","document":"fo","multiple":false},{"enonce":"Range chaque élément dans la bonne peine.","aide":"Le corps d’un côté, l’âme de l’autre.","type":"categories","categories":[{"id":"c0","texte":"Peine ancienne"},{"id":"c1","texte":"Prison moderne"}],"items":[{"id":"i0","texte":"Le spectacle du supplice"},{"id":"i1","texte":"L’échafaud"},{"id":"i2","texte":"L’emploi du temps"},{"id":"i3","texte":"La surveillance continue"},{"id":"i4","texte":"Le panoptique"}]},{"enonce":"Pourquoi le pouvoir du panoptique est-il dit « intérieur » ?","aide":"Il ne sait jamais quand il est vu.","type":"choix","options":[{"id":"a","texte":"Le détenu se surveille lui-même sans savoir quand il est vu"},{"id":"b","texte":"Le détenu choisit lui-même la durée de sa peine"},{"id":"c","texte":"Le détenu est surveillé seulement à l’intérieur de sa cellule"},{"id":"d","texte":"Le détenu est surveillé par un gardien unique et connu"}],"multiple":false}]}$ex$::jsonb,
