   $ex${"titre":"Le masque et le corps vécu","competence":"argumenter","situation":"Une scène imaginée, un passage adapté sur le corps, puis les grands témoignages du chapitre.","documents":[{"id":"mq","type":"texte","genre":"recit","titre":"Un soldat revient","blocs":["Dans un roman imaginé pour l’exercice, un soldat revient de la guerre le visage détruit. Pour sortir dans la rue, il se fabrique des masques."],"source":"Scène imaginée pour l’exercice, dans l’esprit d’*Au revoir là-haut*"},{"id":"mp","type":"texte","genre":"source","titre":"Le corps qu’on est","blocs":["On n’a pas un corps comme on a un objet : on est son corps, et c’est par lui qu’on habite le monde. Un membre perdu peut pourtant continuer de se faire sentir."],"source":"D’après Merleau-Ponty — texte adapté"}],"questions":[{"enonce":"Touche le mot qui montre le soldat devenu image.","aide":"Ce qu’il fabrique pour sortir.","type":"zone","document":"mq","multiple":false},{"enonce":"Que cherche le soldat avec ses masques ?","aide":"Relis le tableau du cours sur *Au revoir là-haut*.","type":"choix","options":[{"id":"a","texte":"Devenir une image faute de redevenir un visage"},{"id":"b","texte":"Retrouver son visage intact grâce à la chirurgie"},{"id":"c","texte":"Se cacher pour éviter toute vie sociale"},{"id":"d","texte":"Prouver que le visage n’a aucune importance"}],"multiple":false},{"enonce":"Associe chaque auteur à son apport.","aide":"Reprends les sections du cours.","type":"association","gauche":[{"id":"g0","texte":"Levinas"},{"id":"g1","texte":"Primo Levi"},{"id":"g2","texte":"Robert Antelme"},{"id":"g3","texte":"Merleau-Ponty"}],"droite":[{"id":"d0","texte":"Il n’existe pas plusieurs espèces humaines"},{"id":"d1","texte":"Le nom remplacé par un numéro"},{"id":"d2","texte":"On est son corps"},{"id":"d3","texte":"Le visage m’oblige"}]},{"enonce":"Que montre le membre fantôme ?","aide":"Le membre n’existe plus, mais il se fait sentir.","type":"choix","options":[{"id":"a","texte":"Que le corps objectif suffit à expliquer l’expérience vécue"},{"id":"b","texte":"Que la douleur est toujours imaginaire et sans cause"},{"id":"c","texte":"Que le corps est un objet comme les autres"},{"id":"d","texte":"Que le corps vécu ne coïncide pas avec le corps objectif"}],"multiple":false}]}$ex$::jsonb,
