   $ex${"titre":"Le carnet d’un ethnomusicologue","competence":"analyser-document","situation":"Une ethnomusicologue note ce qu’elle entend lors d’une veillée. Tu relis ses notes pour identifier deux traditions vocales.","documents":[{"id":"car","type":"texte","genre":"recit","titre":"Carnet d’écoute","blocs":["Un soliste lance une phrase et le chœur lui répond, tandis qu’un kayamb rempli de graines marque le rythme. Les paroles sont en créole.","Plus tard, un chœur puissant chante sans instrument : une voix grave tient une seule note longue pendant que des voix aiguës ornent la mélodie."],"source":"Carnet écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui désigne l’instrument rythmique de la première veillée.","aide":"C’est un hochet rempli de graines.","type":"zone","document":"car","multiple":false},{"enonce":"Range chaque trait du côté du maloya ou des himene.","aide":"Le maloya vient d’Afrique et de Madagascar ; les himene, de la rencontre avec des cantiques.","type":"categories","categories":[{"id":"c0","texte":"Maloya"},{"id":"c1","texte":"Himene"}],"items":[{"id":"i0","texte":"Hochet kayamb"},{"id":"i1","texte":"Chants des esclaves et des engagés"},{"id":"i2","texte":"Chant responsorial"},{"id":"i3","texte":"Bourdon tenu par une voix grave"},{"id":"i4","texte":"Cantiques des missionnaires protestants"},{"id":"i5","texte":"Polyphonie chorale puissante"}]},{"enonce":"Que signifie chanter en créole pour ces musiciens ?","aide":"Le créole est né de la rencontre des langues dans les colonies.","type":"choix","options":[{"id":"a","texte":"Imiter les chansons de la pop mondiale"},{"id":"b","texte":"Éviter toute trace d’histoire coloniale"},{"id":"c","texte":"Rendre la musique plus facile à copier"},{"id":"d","texte":"Affirmer une mémoire et une identité propres"}],"multiple":false}]}$ex$::jsonb,
